    @php
        $grayPic = 'data:image/png;base64,';
        if($userData['profile_picture']){
            $path = $userData['profile_picture'];
            $type = pathinfo($path, PATHINFO_EXTENSION);
            try{
                $data = file_get_contents($path);

                $base64 = 'data:image/' . $type . ';base64,' . base64_encode($data);
            }catch (Exception $e){
                $base64 = $grayPic;
            }


        }else{
            $base64= $grayPic;
        }


    @endphp
